CREATE TABLE IF NOT EXISTS guests (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL COLLATE NOCASE UNIQUE, attendance TEXT NOT NULL, guest_count INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS game_scores (id INTEGER PRIMARY KEY AUTOINCREMENT, guest_id INTEGER NOT NULL REFERENCES guests(id) ON DELETE CASCADE, game_id TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0, finished_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(guest_id, game_id));
CREATE INDEX IF NOT EXISTS idx_guests_attendance_name ON guests(attendance, name);
CREATE INDEX IF NOT EXISTS idx_scores_guest_finished ON game_scores(guest_id, finished_at);

